mapper.select:
SELECT InAmt.코드 As inputCode, InAmt.날짜 as inputDate, InAmt.이름1 as inputNm1, InAmt.이름2 as inputNm2, InAmt.이름3 as inputNm3, InAmt.금액 as inputAmt, InAmt.비고 as inputCnt, InAmt.성도코드1 as inputFmCd1, InAmt.성도코드2 as inputFmCd2, InAmt.분류 as inputKind, InAmt.계정코드2 as inputFlCode2, InAmt.계정코드3 as inputFlCode3, InAmt.코드분류 as codeType, CoutConf2.항 As inputFlNm2, CoutConf3.목 As inputFlNm3, InAmt.년도 As year FROM 수입 InAmt, 수입항 CoutConf2, 수입목 CoutConf3 WHERE InAmt.계정코드2 = CoutConf2.항코드 AND InAmt.코드분류 = CoutConf2.코드분류 AND InAmt.코드분류 = CoutConf3.코드분류 AND InAmt.계정코드2 = CoutConf3.항코드 AND InAmt.계정코드3 = CoutConf3.목코드
AND InAmt.코드분류 = #{codeType}
AND InAmt.년도 = #{year}
AND InAmt.코드 = #{inputCode}
AND InAmt.코드 = #{inputCode}
AND InAmt.코드 = (Select Max(코드) From 수입)

SELECT InAmt.코드 As inputCode, InAmt.날짜 as inputDate, InAmt.이름1 as inputNm1, InAmt.이름2 as inputNm2, InAmt.이름3 as inputNm3, InAmt.금액 as inputAmt, InAmt.비고 as inputCnt, InAmt.성도코드1 as inputFmCd1, InAmt.성도코드2 as inputFmCd2, InAmt.분류 as inputKind, InAmt.계정코드2 as inputFlCode2, InAmt.계정코드3 as inputFlCode3, InAmt.코드분류 as codeGb, CoutConf2.항 As inputFlNm2, CoutConf3.목 As inputFlNm3, InAmt.년도 As year FROM 수입 InAmt, 수입항 CoutConf2, 수입목 CoutConf3 WHERE InAmt.계정코드2 = CoutConf2.항코드 AND InAmt.코드분류 = CoutConf2.코드분류 AND InAmt.코드분류 = CoutConf3.코드분류 AND InAmt.계정코드2 = CoutConf3.항코드 AND InAmt.계정코드3 = CoutConf3.목코드
AND InAmt.코드분류 = #{codeGb}
AND InAmt.년도 = #{year}
AND ( InAmt.성도코드1 in (SELECT 개인번호 FROM 가족구성원 where 대표번호 = #{baseCode} ) OR InAmt.성도코드2 in (SELECT 개인번호 FROM 가족구성원 where 대표번호 = #{baseCode} ))
AND InAmt.코드 = #{inputCode}
AND InAmt.날짜 >= #{fmInputDate}
AND InAmt.날짜 <= #{toInputDate}
AND InAmt.성도코드1 = #{inputFmCd1}
AND mid(InAmt.성도코드1,1,5) = substring(#{inputFmCd2},0,5)
AND (InAmt.이름1 like '%'||#{inputNm1}||'%' or InAmt.이름2 like '%'||#{inputNm1}||'%')
AND (InAmt.성도코드1 = #{inputFmCd1} or InAmt.성도코드2 = #{inputFmCd1})
AND InAmt.계정코드2 = #{inputFlCode2}
AND InAmt.계정코드3 = #{inputFlCode3}
AND InAmt.비고 = '%'||#{inputCnt}||'%'
Order by InAmt.날짜,InAmt.코드 desc, InAmt.코드

SELECT InAmt.코드 As inputCode, InAmt.날짜 as inputDate, InAmt.이름1 as inputNm1, InAmt.이름2 as inputNm2, InAmt.금액 as inputAmt, InAmt.비고 as inputCnt, InAmt.성도코드1 as inputFmCd1, InAmt.성도코드2 as inputFmCd2, InAmt.분류 as inputKind, InAmt.코드분류 as codeType, InAmt.년도 As year FROM 주일헌금 InAmt WHERE 1 = 1
AND InAmt.코드분류 = #{codeType}
AND InAmt.년도 = #{year}
AND InAmt.코드 = #{inputCode}
AND InAmt.코드 = #{inputCode}
AND InAmt.코드 = (Select Max(코드) From 주일헌금)

SELECT InAmt.코드 As inputCode, InAmt.날짜 as inputDate, InAmt.이름1 as inputNm1, InAmt.이름2 as inputNm2, InAmt.금액 as inputAmt, InAmt.비고 as inputCnt, InAmt.성도코드1 as inputFmCd1, InAmt.성도코드2 as inputFmCd2, InAmt.분류 as inputKind, InAmt.코드분류 as codeGb, InAmt.년도 As year FROM 주일헌금 InAmt WHERE 1 = 1
AND InAmt.코드분류 = #{codeGb}
AND InAmt.년도 = #{year}
AND InAmt.코드 = #{inputCode}
AND ( InAmt.성도코드1 in (SELECT 개인번호 FROM 가족구성원 where 대표번호 = #{baseCode} ) OR InAmt.성도코드2 in (SELECT 개인번호 FROM 가족구성원 where 대표번호 = #{baseCode} ))
AND InAmt.날짜 >= #{fmInputDate}
AND InAmt.날짜 <= #{toInputDate}
AND (InAmt.성도코드1 = #{inputFmCd1} OR InAmt.성도코드2 = #{inputFmCd1})
AND (InAmt.이름1 like '%'||#{inputNm1}||'%' or InAmt.이름2 like '%'||#{inputNm1}||'%')
AND mid(InAmt.성도코드1,1,5) = substring(#{inputFmCd2},0,5)
Order by InAmt.날짜, InAmt.코드 desc
